'use strict';
const $=s=>document.querySelector(s);
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='aiguillage-v4';
const CATEGORIES={
  clinique:{label:'Clinique',color:'#146b62',description:'Trajectoires, comorbidités et choix de soin'},
  ethique:{label:'Éthique',color:'#925622',description:'Valeurs, préférences et place de chacun'},
  epistemologie:{label:'Épistémologie',color:'#6b4f91',description:'Ce que l’on sait, ce que l’on suppose'},
  acces:{label:'Accès aux soins',color:'#9b3f57',description:'Les conditions réelles pour bénéficier du soin'},
  organisation:{label:'Organisation',color:'#38678a',description:'Temps, parcours et coopération'},
  institution:{label:'Institution',color:'#52683b',description:'Règles, moyens et responsabilité collective'}
};
const blank=()=>({view:'home',index:0,phase:'choose',profile:null,profileAsked:false,first:null,chosen:null,revised:false,records:[],third:false,route:[],category:'all',length:'8',seen:[]});
let state=blank(),soundOn=false,animation=0,audioCtx=null,dragStart=null;
try{
  const saved=JSON.parse(sessionStorage.getItem(STORAGE));
  if(saved&&Array.isArray(saved.route)&&saved.route.every(id=>CASES.some(c=>c.id===id))&&Array.isArray(saved.records)&&saved.records.every(r=>CASES.some(c=>c.id===r.id))){
    state={...state,...saved};
    if(!CATEGORIES[state.category]&&state.category!=='all')state.category='all';
    if(!['8','all'].includes(state.length))state.length='8';
    if(!Array.isArray(state.seen))state.seen=[];
    if(state.phase==='travel')state.phase='arrived';
    if(state.index<0||state.index>=state.route.length){state.view='home';state.index=0;}
  }else{
    const previous=JSON.parse(sessionStorage.getItem('aiguillage-v3'));
    if(previous){state.profile=previous.profile||null;state.profileAsked=!!previous.profileAsked;}
  }
}catch{}
function pool(){return CASES.filter(c=>state.category==='all'||c.category===state.category);}
function shuffled(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
function makeRoute(){
  const available=pool();
  const count=state.length==='all'?available.length:Math.min(8,available.length);
  const ordered=shuffled(available).sort((a,b)=>Number(state.seen.includes(a.id))-Number(state.seen.includes(b.id)));
  if(state.category!=='all'||count===available.length)return ordered.slice(0,count).map(c=>c.id);
  const clinical=ordered.filter(c=>c.category==='clinique').slice(0,4);
  const other=[];
  for(const key of shuffled(Object.keys(CATEGORIES).filter(k=>k!=='clinique'))){const next=ordered.find(c=>c.category===key);if(next)other.push(next);}
  const selected=[...clinical,...other.slice(0,count-clinical.length)];
  for(const c of ordered){if(selected.length>=count)break;if(!selected.some(x=>x.id===c.id))selected.push(c);}
  return shuffled(selected).map(c=>c.id);
}
function beginRoute(ids){
  const {profile,profileAsked,category,length,seen}=state;
  state={...blank(),profile,profileAsked,category,length,seen,route:ids||makeRoute()};
  if(state.profileAsked)launch();else profileForm();
}
function caseCategory(c){return CATEGORIES[c.category]||CATEGORIES.clinique;}
function categoryMarkup(c){const cat=caseCategory(c);return `<span class="category-tag" style="--category:${cat.color}">${cat.label}</span>`;}
function references(c){return (c.sources||[]).map(key=>{const ref=typeof SOURCES!=='undefined'?SOURCES[key]:null;if(!ref)return '';return ref.url?`<a href="${escapeHTML(ref.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(ref.title)} ↗</a>`:`<span>${escapeHTML(ref.title)}</span>`;}).join('');}
function save(){try{sessionStorage.setItem(STORAGE,JSON.stringify(state));}catch{}}
function announce(t){$('#live').textContent=t;}
function toast(t){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),3000);announce(t);}
function current(){return CASES.find(c=>c.id===state.route[state.index]);}
function bell(){if(!soundOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();[880,1175].forEach((freq,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,audioCtx.currentTime+i*.11);g.gain.linearRampToValueAtTime(.08,audioCtx.currentTime+i*.11+.012);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+i*.11+.65);o.connect(g);g.connect(audioCtx.destination);o.start(audioCtx.currentTime+i*.11);o.stop(audioCtx.currentTime+i*.11+.7);});}catch{}}
function person(x,y,i,child=false){return `<g class="sketch" transform="translate(${x} ${y}) scale(${child?.84:1})"><path d="M-11-55q0-18 12-18 13 0 12 18v7q-2 12-12 12-11 0-12-12Z" fill="${i%3===0?'#f1c45e':'#fffdf7'}"/><path d="M-10-62q5-18 21-2M-14-29q14-8 28 0l6 36h-40Z" fill="${i%2?'#e9edf6':'#fffdf7'}"/><path d="M-6 8-7 36m15-28 5 28M-7 36h-9m29 0h9M-14-23l-13 25m41-25 13 25"/><path d="M-3-49h1m8 0h1m-7 8q3 2 6 0"/></g>`;}
function prop(name,x,y){const shapes={calendar:'<rect x="-18" y="-20" width="36" height="36" fill="#fffdf7"/><path d="M-18-10h36M-8-25v10M8-25v10m-16 12h16M-8 6h8"/>',clock:'<circle r="21" fill="#fffdf7"/><path d="M0-14V1l10 7"/>',cloud:'<path d="M-25 9q-15-14 2-22 2-20 23-10 18-8 22 9 19 6 8 23Z" fill="#e9edf6"/><path d="m-12 18-3 7m15-6-3 7m15-8-3 7"/>',bubble:'<path d="M-25-20h50v34H3l-12 13v-13h-16Z" fill="#fffdf7"/><path d="M-14-8h27M-14 2h17"/>',ten:'<text x="0" y="8" text-anchor="middle" stroke="none" fill="#465ca0" font-family="Bricolage Grotesque, sans-serif" font-size="28">10</text>',two:'<text x="0" y="8" text-anchor="middle" stroke="none" fill="#465ca0" font-family="Bricolage Grotesque, sans-serif" font-size="28">2</text>',label:'<path d="M-22-18h33l14 18-14 18h-33Z" fill="#f1c45e"/><circle cx="12" r="3"/><path d="M-14-5H0M-14 5h16"/>',letter:'<rect x="-25" y="-17" width="50" height="34" fill="#fffdf7"/><path d="m-25-17 25 21 25-21"/>',quiet:'<path d="M-25 15v-34h49v34M-12 15v-23h24v23"/><path d="M-6-32q9-9 18 0m-12-8q4-5 8 0"/>',speech:'<path d="M-29-19H9V7H-8l-9 10V7h-12Z" fill="#fffdf7"/><path d="M0-5h29v25H17l-7 8v-8H0Z" fill="#e9edf6"/>',fast:'<circle cx="7" r="21" fill="#fffdf7"/><path d="M7-13V0l9 5M-32-13h13m-20 13h19m-14 13h14"/>',question:'<text x="0" y="17" text-anchor="middle" stroke="none" fill="#465ca0" font-family="Bricolage Grotesque, sans-serif" font-size="58">?</text>',stamp:'<path d="M-24 9h48v9h-48ZM-7 9V-4q-15-27 7-27T7-4V9" fill="#f1c45e"/>'};return `<g class="sketch" transform="translate(${x} ${y})">${shapes[name]||shapes.clock}</g>`;}
function station(option,key,y,mobile,home=false){const nameX=mobile?270:535,platformX=mobile?450:930,scale=mobile?.76:1;const dim=!home&&state.phase!=='choose'&&state.chosen!==key;const arrived=!home&&state.phase==='arrived'&&state.chosen===key;return `<g class="station-scene ${dim?'dimmed':''} ${arrived?'arrived':''}" id="station-${key}"><text class="station-letter" x="${nameX}" y="${y-(mobile?185:145)}">QUAI ${key==='a'?'01':'02'}</text><text class="station-name" x="${nameX}" y="${y-(mobile?160:120)}">${escapeHTML(option.name)}</text><text class="station-detail" x="${nameX}" y="${y-(mobile?132:96)}">${escapeHTML(option.detail)}</text><g transform="translate(${platformX} ${y-38}) scale(${scale})"><g class="sketch shelter-line"><path d="M-54 30h165M-39 30v-90h135v90M-48-60 26-82l81 22"/><path d="M-29 9h116M-22 9v21m101-21v21"/><path d="M-54 34h165"/></g>${Array.from({length:Math.min(option.people,5)},(_,i)=>person(-12+i*25,-11,i,i===0||i===3)).join('')}</g>${prop(option.prop,mobile?350:712,y+43)}</g>`;}
function tram(cargo){return `<g id="tram"><ellipse cx="0" cy="12" rx="56" ry="8" fill="#282b30" opacity=".08"/><g class="sketch"><path d="M-48-66h89l8 12V-5h-97Z" fill="#db442e"/><path d="M-53-66q48-11 99 0l5 7H-55Z" fill="#fffdf7"/><path d="M-39-52h23v25h-23Zm33 0h22v25H-6Zm32 0h17v25H26Z" fill="#e9edf6"/><path d="M-3-68 8-88 22-68M-2-89h31"/><path d="M-51-5h104v6H-51Z" fill="#f1c45e"/><circle cx="-30" cy="5" r="8" fill="#282b30"/><circle cx="30" cy="5" r="8" fill="#282b30"/><circle cx="-30" cy="5" r="3" fill="#fffdf7"/><circle cx="30" cy="5" r="3" fill="#fffdf7"/><path d="M49-18h8v9h-8M-48-17h-7v8h7"/><circle cx="34" cy="-41" r="5" fill="#fffdf7"/><path d="m30-35-4 8"/><path d="M-42-13H40" stroke="#fffdf7" opacity=".5"/></g><text class="cargo" text-anchor="middle" x="0" y="-16">${escapeHTML(cargo)}</text></g>`;}
function geometry(mobile){return mobile?{view:'0 0 600 620',a:'M-45 340 L160 340 C230 340 240 200 330 200 L570 200',b:'M-45 340 L160 340 C240 340 240 490 330 490 L570 490',ay:200,by:490,start:135,end:560}:{view:'0 0 1100 560',a:'M-80 310 L300 310 C405 310 420 170 550 170 L1050 170',b:'M-80 310 L300 310 C405 310 420 430 550 430 L1050 430',ay:170,by:430,start:230,end:1035};}
function scene(home=false){const mobile=window.innerWidth<=600,g=geometry(mobile),c=home?{cargo:'ET VOUS ?',a:{name:'Option 1',detail:'Garder la direction du haut',people:3,prop:'clock'},b:{name:'Option 2',detail:'Actionner la manette vers le bas',people:2,prop:'question'}}:current();return `<div class="stage-wrap ${home?'welcome-stage':'game-stage'}"><div class="stage ${mobile?'mobile-scene':''}"><svg class="scene" viewBox="${g.view}" role="img" aria-label="Un tramway rouge attend devant un aiguillage — Voie du haut : ${escapeHTML(c.a.name)} — Voie du bas : ${escapeHTML(c.b.name)}"><defs><pattern id="paper-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#465ca0" stroke-opacity=".035" stroke-width="1"/></pattern></defs><rect width="1100" height="620" fill="url(#paper-grid)"/><path class="line-guide" d="${mobile?'M80 100h470M80 560h470M580 70v510':'M60 80h980M60 505h980M1060 40v470'}"/><g><path class="track-shadow" d="${g.a}"/><path class="track-shadow" d="${g.b}"/><g class="ties" id="ties-a"></g><g class="ties" id="ties-b"></g><path id="path-a" class="track" d="${g.a}" transform="translate(0 -5)"/><path class="track" d="${g.a}" transform="translate(0 5)"/><path id="path-b" class="track" d="${g.b}" transform="translate(0 -5)"/><path class="track" d="${g.b}" transform="translate(0 5)"/></g>${station(c.a,'a',g.ay,mobile,home)}${station(c.b,'b',g.by,mobile,home)}${state.third&&!home?`<path class="third-track" d="${mobile?'M160 340H570':'M300 310H1050'}"/><text class="third-label" x="${mobile?300:600}" y="${mobile?320:292}">Combiner les deux options</text>`:''}${tram(c.cargo)}<g class="sketch" transform="translate(${mobile?93:205} ${mobile?286:258})"><path d="M0 0V39m-10 0h20"/><rect x="-9" y="-30" width="18" height="32" rx="6" fill="#fffdf7"/><circle cx="0" cy="-21" r="4" fill="${!home&&state.phase==='travel'?'#8a9f82':'#db442e'}"/><circle cx="0" cy="-8" r="4" fill="${!home&&state.phase==='travel'?'#8a9f82':'#e9edf6'}"/></g></svg><button class="lever-control ${state.chosen==='b'&&!home?'pulled':''}" data-action="lever" aria-label="${home?'Essayer la manette et commencer':'Actionner la manette : '+escapeHTML(c.b.name)}" ${!home&&state.phase!=='choose'?'disabled':''}><svg viewBox="0 0 150 160" aria-hidden="true"><path d="M49 108q26-12 50 0l-4 18H53Z" fill="#e9edf6" stroke="#282b30" stroke-width="2"/><path d="M59 112h31" stroke="#282b30"/><g class="lever-arm"><path d="M75 109 43 40" stroke="#282b30" stroke-width="7" stroke-linecap="round"/><path d="m75 106-30-63" stroke="#fffdf7" stroke-width="1.5"/><circle class="knob" cx="42" cy="37" r="15"/></g><circle cx="75" cy="109" r="5" fill="#fffdf7" stroke="#282b30" stroke-width="2"/><g class="pull-hint"><path d="M20 44Q1 69 20 89m-12-1 12 1 1-12" fill="none" stroke="#465ca0" stroke-width="1.5"/><text class="lever-label" x="26" y="151">la manette</text></g></svg></button>${home?'':`<button class="pass-button" data-action="pass" ${state.phase!=='choose'?'disabled':''}>Laisser filer →<span>vers « ${escapeHTML(c.a.name)} »</span></button><div class="direction-note">Le tram transporte<br>${c.cargo.toLowerCase()}<br>Pas les patients</div>${state.phase==='travel'?'<div class="travel-note" role="status">Le tram rejoint la voie choisie</div>':''}`}</div>${!home&&state.phase==='choose'?'<p class="route-hint">Actionnez la manette pour prendre la voie du bas</p>':''}</div>`;}
function welcome(){const available=pool();const count=state.length==='all'?available.length:Math.min(8,available.length);return `<section class="welcome"><div class="welcome-copy"><div class="eyebrow">Dilemmes de soin · Enfance & adolescence</div><h1>Vous avez<br><span>la manette</span></h1><p>Un tramway, deux voies<br>Choisissez une priorité de soin</p></div><div class="boarding"><div class="boarding-top"><span class="boarding-no">${CASES.length}</span><span>situations<br>disponibles</span><button class="catalog-link" data-action="catalog">Voir les situations ↗</button></div><label class="select-label" for="route-category">CHOISISSEZ UNE CATÉGORIE</label><select id="route-category"><option value="all" ${state.category==='all'?'selected':''}>Toutes les catégories</option>${Object.entries(CATEGORIES).map(([key,c])=>`<option value="${key}" ${state.category===key?'selected':''}>${c.label} · ${CASES.filter(x=>x.category===key).length}</option>`).join('')}</select><p class="line-description">${state.category==='all'?'Situations cliniques, éthiques et organisationnelles':CATEGORIES[state.category].description}</p><div class="trip-length" role="group" aria-label="Nombre de situations"><button data-action="length-short" aria-pressed="${state.length==='8'}">Parcours court</button><button data-action="length-all" aria-pressed="${state.length==='all'}">Toutes les situations</button></div><button class="ticket" data-action="start">Commencer · ${count} situations <span>→</span></button>${state.route.length?'<button class="welcome-resume" data-action="resume">Reprendre le parcours</button>':''}</div></section>${scene(true)}<div class="line-legend">${Object.entries(CATEGORIES).map(([key,cat])=>`<button data-category="${key}" style="--category:${cat.color}" aria-pressed="${state.category===key}"><span></span>${cat.label}</button>`).join('')}</div>`;}
function dispatch(){const c=current(),chosen=c[state.chosen],o=c.outcomes[state.chosen==='a'?0:1];return `<section class="dispatch" aria-label="Conséquences du choix"><div class="dispatch-rule"><p class="receipt-title">Votre choix : ${escapeHTML(chosen.name)}</p><div class="outcome"><p><b>PRIORITÉ RETENUE</b>${o[0]}</p><p><b>LIMITES DE CE CHOIX</b>${o[1]}</p></div>${!state.revised?`<p class="twist"><span>Nouvelle information</span>${c.twist}</p>`:`<p class="twist"><span>Après réévaluation</span>${state.first===state.chosen?'Vous maintenez votre choix après avoir pris connaissance de la nouvelle information':'Vous avez changé de choix après la nouvelle information, votre décision initiale figure dans le récapitulatif'}</p>`}${c.third&&!state.third?'<button class="third-btn" data-action="third">Combiner les deux options ↗</button>':''}${state.third?`<p class="twist"><span>Une option combinée</span>${c.thirdText}</p>`:''}<details class="debrief"><summary>Questions de discussion</summary><p>${c.discussion}</p><div class="references">${references(c)}</div></details><div class="dispatch-actions">${!state.revised&&!state.third?'<button class="plain-btn" data-action="revise">↶ Réexaminer mon choix</button>':'<span></span>'}<button class="next-btn" data-action="next">${state.index===state.route.length-1?'Voir le récapitulatif':'Situation suivante'}<span>→</span></button></div></div></section>`;}
function game(){const c=current();return `<button class="pause-link" data-action="pause">Retour à l’accueil</button><section class="intro-head"><div class="route-meta">${categoryMarkup(c)}<span>SITUATION ${String(state.index+1).padStart(2,'0')} / ${String(state.route.length).padStart(2,'0')}</span></div><div class="case-topic">${escapeHTML(c.topic||'')}</div><h1>${c.title}</h1><p class="story">${c.intro}</p><p class="aside">${c.aside}</p></section>${state.revised&&state.phase==='choose'?`<div class="revision-banner"><b>NOUVELLE INFORMATION</b>${c.twist}</div>`:''}${scene()}${state.phase==='arrived'?dispatch():''}`;}
function end(){return `<section class="end"><div class="route-meta">FIN DU PARCOURS</div><h1>Récapitulatif<br><em>de vos choix</em></h1><p class="end-intro">${state.records.length} situations examinées<br>Retrouvez vos choix, les questions de discussion et les références</p><div class="end-map">${state.records.map(r=>{const c=CASES.find(x=>x.id===r.id);return `<div class="end-stop">${categoryMarkup(c)}<h3>${c.title}</h3><p>${escapeHTML(c[r.final].name)}</p>${r.third?'<small>↗ Vous avez examiné une option combinée</small>':r.first!==r.final?`<small>↶ D’abord : ${escapeHTML(c[r.first].name)}</small>`:''}<details><summary>Questions de discussion</summary><p>${c.discussion}</p><div class="references">${references(c)}</div></details></div>`;}).join('')}</div><div class="end-actions"><button class="ticket" data-action="home">Choisir un autre parcours <span>↗</span></button><button class="plain-btn" data-action="export">Exporter mes choix ↓</button></div><p class="fineprint">Le profil et les réponses restent dans cet onglet</p></section>`;}
function setupScene(){const mobile=window.innerWidth<=600,g=geometry(mobile);for(const k of ['a','b']){const p=$('#path-'+k),group=$('#ties-'+k);if(!p||!group)continue;const len=p.getTotalLength();let ties='';for(let l=10;l<len;l+=18){const a=p.getPointAtLength(l),b=p.getPointAtLength(Math.min(l+1,len)),angle=Math.atan2(b.y-a.y,b.x-a.x)+Math.PI/2;ties+=`<line x1="${a.x-Math.cos(angle)*11}" y1="${a.y-Math.sin(angle)*11}" x2="${a.x+Math.cos(angle)*11}" y2="${a.y+Math.sin(angle)*11}"/>`;}group.innerHTML=ties;}const p=$('#path-'+(state.view==='game'&&state.phase==='arrived'?state.chosen:'a'));if(p){const at=state.view==='game'&&state.phase==='arrived'?p.getTotalLength()-65:g.start;positionTram(p,at);}}
function positionTram(path,length){const p=path.getPointAtLength(length),next=path.getPointAtLength(Math.min(length+2,path.getTotalLength())),angle=Math.atan2(next.y-p.y,next.x-p.x)*180/Math.PI;$('#tram')?.setAttribute('transform',`translate(${p.x} ${p.y}) rotate(${angle*.28})`);}
function render(focus=true){cancelAnimationFrame(animation);$('#main').innerHTML=state.view==='home'?welcome():state.view==='end'?end():game();setupScene();save();if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}}
function ride(branch){if(state.view!=='game'||state.phase!=='choose')return;if(state.first===null)state.first=branch;state.chosen=branch;state.phase='travel';render(false);bell();const path=$('#path-'+branch),g=geometry(window.innerWidth<=600),length=path.getTotalLength(),from=g.start,to=length-65,duration=window.matchMedia('(prefers-reduced-motion: reduce)').matches?120:2100;let start=null;function frame(time){start??=time;const t=Math.min((time-start)/duration,1),ease=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;positionTram(path,from+(to-from)*ease);if(t<1){animation=requestAnimationFrame(frame);}else{state.phase='arrived';render(false);announce('Option choisie : '+current()[branch].name+' — '+current().twist);$('.dispatch')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}}animation=requestAnimationFrame(frame);}
function openDialog(title,html){$('#dialog-body').innerHTML=`<h2 id="dialog-title">${title}</h2>${html}`;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function launch(){closeDialog();state.view='game';render();}
function start(){beginRoute();}
function profileForm(){openDialog('Votre profil facultatif',`<div class="ticket-id">AUCUN CHAMP OBLIGATOIRE</div><p>Vous pouvez renseigner quelques informations sur votre pratique ou commencer sans profil</p><form id="profile-form"><div class="form-grid"><label>ÂGE<input name="age" type="number" min="0" max="120" step="1" inputmode="numeric" placeholder="En années"></label><label>GENRE<select name="gender"><option value="">Ne pas préciser</option><option>Femme</option><option>Homme</option><option>Non binaire</option><option>Autre</option></select></label><label class="full">PROFESSION / FORMATION — CHAMP LIBRE<input name="profession" maxlength="120" placeholder="Exemple : psychologue, interne, étudiant…" autocomplete="off"></label><label>ANNÉES DE PRATIQUE<input id="years" name="years" type="number" min="0" max="80" step="0.5" placeholder="Exemple : 4" inputmode="decimal"><small>Depuis le début de l’internat si pertinent</small></label><label>VILLE D’EXERCICE / D’ÉTUDES<input name="city" maxlength="100" placeholder="Facultatif" autocomplete="off"></label></div><label class="check"><input name="notApplicable" type="checkbox"> Les années de pratique ne s’appliquent pas à ma situation</label><div class="form-actions"><button class="plain-btn" type="button" data-action="skip-profile">Commencer sans profil →</button><button class="ticket" type="submit">Commencer <span>→</span></button></div><p class="fineprint">Aucun nom ni e-mail · Ce profil reste dans la session du navigateur<br>Âge + profession + ville peuvent cependant rendre quelqu’un reconnaissable : laissez les champs trop précis vides<br>Aucune information sur un patient réel</p></form>`);}
function about(){openDialog('À propos de L’Aiguillage',`<p>${CASES.length} dilemmes pour des praticiens expérimentés, répartis en six registres<br>Choisissez un parcours court, toutes les situations d’une catégorie ou une situation précise dans le catalogue</p><h3>Vous avez la manette</h3><p>Laissez filer le tram vers le quai du haut, ou cliquez sur la manette pour le diriger en bas<br>Vous pouvez aussi tirer la manette vers le bas ou utiliser Tab puis Entrée au clavier</p><p>Une information arrive après votre choix<br>Vous pouvez réexaminer votre choix, puis consulter les questions de discussion</p><h3>Les choix proposés</h3><p>Des priorités de soin, des méthodes d’évaluation et des contraintes de moyens<br>Les options du jeu sont délibérément resserrées ; elles peuvent se combiner dans la pratique</p><p>Les situations sont fictives et ne constituent ni des recommandations individualisées ni un outil de triage<br>Les situations d’urgence ne sont jamais une option facultative du jeu</p><h3>Références</h3><p>Référentiel de psychiatrie et addictologie, 4e édition, CNUP–AESP–CUNEA, PUFR, 2024 — utilisé pour couvrir les champs cliniques</p><p>PhiloPsy — Christophe Gauld & Jean-Arthur Micoulaud-Franchi — pour les questions de connaissance, de valeurs et de classification</p><p>Les vignettes sont originales et ne reproduisent pas le référentiel<br>Les références HAS et NICE sont accessibles sous les questions de discussion</p><p>La mécanique s’inspire d’<a href="https://neal.fun/absurd-trolley-problems/" target="_blank" rel="noopener noreferrer">Absurd Trolley Problems</a><br>Dessins et situations de L’Aiguillage créés pour ce jeu</p><p>Typographies Bricolage Grotesque et DM Sans, distribuées sous licence SIL Open Font License</p>`);}
function catalog(){openDialog('Catalogue des situations',`<label class="catalog-search">CHERCHER UNE SITUATION<input id="case-search" type="search" placeholder="TDAH, parents, sommeil…" autocomplete="off"></label><div id="catalog-list">${catalogList('')}</div>`);}
function catalogList(query){const normalize=t=>t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=normalize(query.trim());const results=CASES.filter(c=>normalize(c.title+' '+(c.topic||'')+' '+caseCategory(c).label+' '+c.intro).includes(q));return results.length?Object.entries(CATEGORIES).map(([key,cat])=>{const list=results.filter(c=>c.category===key);return list.length?`<section class="catalog-group"><h3 style="--category:${cat.color}">${cat.label} <small>${list.length}</small></h3>${list.map(c=>`<button data-case-id="${c.id}"><span>${escapeHTML(c.title)}</span><small>${escapeHTML(c.topic||'')}</small><b aria-hidden="true">↗</b></button>`).join('')}</section>`:'';}).join(''):'<p>Aucune situation ne correspond à cette recherche</p>';}
document.addEventListener('input',e=>{if(e.target.id==='case-search')$('#catalog-list').innerHTML=catalogList(e.target.value);});
function privacy(){openDialog('Le profil & vos données',`<p>Le profil et les réponses restent dans la mémoire et le stockage de session de cet onglet<br>Le jeu ne les envoie pas à une base de réponses<br>Fermer l’onglet termine normalement la session, mais certains navigateurs peuvent la restaurer</p><p>Aucun traceur d’audience n’est ajouté<br>L’hébergement peut traiter les informations techniques habituelles de connexion : l’anonymat de la navigation n’est pas garanti</p><h3>Votre profil</h3><p>${state.profile?`Âge : ${escapeHTML(state.profile.age??'non précisé')}<br>Genre : ${escapeHTML(state.profile.gender||'non précisé')}<br>Profession : ${escapeHTML(state.profile.profession||'non précisée')}<br>Pratique : ${state.profile.notApplicable?'non applicable':escapeHTML(state.profile.years??'non précisée')}<br>Ville : ${escapeHTML(state.profile.city||'non précisée')}`:'Aucun profil renseigné'}</p><p>Les informations sociodémographiques sont exclues de l’export par défaut<br>Leur combinaison peut permettre une réidentification</p><div class="dialog-actions"><button data-action="erase-profile">Effacer le profil</button><button data-action="export">Exporter les choix</button><button data-action="erase-prompt">Effacer la session</button></div>`);}
function exportDialog(){openDialog('Exporter vos choix',`<p>L’export contient les ${state.records.length} situations terminées, le choix initial, le choix final et les questions de discussion<br>La situation en cours sera incluse une fois terminée</p><label class="check"><input id="include-profile" type="checkbox"> Inclure aussi mon profil sociodémographique</label><div class="dialog-actions"><button data-action="download-json">Télécharger en JSON</button><button data-action="download-csv">Télécharger en CSV</button></div>`);}
function exportData(include){return{game:'L’Aiguillage',version:4,...(include?{profile:state.profile}:{}),journey:state.records.map(r=>{const c=CASES.find(c=>c.id===r.id);return{id:r.id,situation:c.title,category:caseCategory(c).label,topic:c.topic,first:c[r.first].name,final:c[r.final].name,replayed:r.revised,thirdRoute:r.third,discussion:c.discussion};})};}
function download(format){const include=$('#include-profile').checked,data=exportData(include);let text;if(format==='json')text=JSON.stringify(data,null,2);else{const keys=['age','gender','profession','years','notApplicable','city'];const cell=v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[['situation','categorie','theme','premiere_voie','derniere_voie','rejoue','troisieme_voie','discussion',...(include?keys:[])],...data.journey.map(r=>[r.situation,r.category,r.topic,r.first,r.final,r.replayed,r.thirdRoute,r.discussion,...(include?keys.map(k=>state.profile?.[k]??''):[])])];text='\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n');}const url=URL.createObjectURL(new Blob([text],{type:format==='json'?'application/json':'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='aiguillage-carnet.'+format;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);closeDialog();toast('Votre export est prêt');}
function resetGame(){cancelAnimationFrame(animation);beginRoute();}
function next(){if(state.phase!=='arrived')return;const record={id:current().id,first:state.first,final:state.chosen,revised:state.revised,third:state.third};state.records=state.records.filter(r=>r.id!==record.id);state.records.push(record);if(!state.seen.includes(record.id))state.seen.push(record.id);if(state.index===state.route.length-1){state.view='end';render();return;}state.index++;state.first=null;state.chosen=null;state.revised=false;state.third=false;state.phase='choose';render();}
let suppressClick=false;
function action(a){switch(a){case'home':case'pause':if(state.phase==='travel')return;state.view='home';render();break;case'start':start();break;case'catalog':catalog();break;case'length-short':state.length='8';render(false);break;case'length-all':state.length='all';render(false);break;case'resume':state.view=state.records.length===state.route.length?'end':'game';render();break;case'close':closeDialog();break;case'skip-profile':state.profile=null;state.profileAsked=true;launch();break;case'lever':if(state.view==='home'){start();}else ride('b');break;case'pass':ride('a');break;case'revise':state.revised=true;state.phase='choose';state.chosen=null;render();break;case'next':next();break;case'third':state.third=true;render(false);announce('L’option combinée est affichée');break;case'about':about();break;case'privacy':privacy();break;case'sound':soundOn=!soundOn;$('#sound').innerHTML='♪<span>'+(soundOn?'on':'off')+'</span>';$('#sound').setAttribute('aria-label',soundOn?'Couper le son':'Activer le son');$('#sound').title=soundOn?'Couper le son':'Activer le son';if(soundOn)bell();break;case'restart':resetGame();break;case'export':exportDialog();break;case'download-json':download('json');break;case'download-csv':download('csv');break;case'erase-profile':state.profile=null;save();privacy();break;case'erase-prompt':openDialog('Effacer la session ?',`<p>Le profil, les réponses et la progression de cet onglet seront effacés<br>Les exports déjà téléchargés resteront sur votre appareil</p><div class="dialog-actions"><button data-action="erase">Effacer cette session</button><button data-action="close">Conserver la session</button></div>`);break;case'erase':state=blank();save();closeDialog();render();break;}}
document.addEventListener('click',e=>{const category=e.target.closest('[data-category]');if(category){state.category=category.dataset.category;render(false);return;}const selected=e.target.closest('[data-case-id]');if(selected){closeDialog();beginRoute([selected.dataset.caseId]);return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;if(suppressClick&&b.dataset.action==='lever'){suppressClick=false;return;}action(b.dataset.action);});
document.addEventListener('pointerdown',e=>{const b=e.target.closest('.lever-control');if(!b||b.disabled)return;dragStart={y:e.clientY,button:b};b.setPointerCapture?.(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!dragStart)return;const dy=e.clientY-dragStart.y;const arm=dragStart.button.querySelector('.lever-arm');if(arm)arm.style.transform=`rotate(${-Math.max(0,Math.min(dy,65))}deg)`;});
document.addEventListener('pointerup',e=>{if(!dragStart)return;const dy=e.clientY-dragStart.y;dragStart.button.querySelector('.lever-arm').style.transform='';dragStart=null;if(dy>20){suppressClick=true;action('lever');setTimeout(()=>suppressClick=false,350);}});
document.addEventListener('pointercancel',()=>{if(dragStart)dragStart.button.querySelector('.lever-arm').style.transform='';dragStart=null;});
document.addEventListener('change',e=>{if(e.target.id==='route-category'){state.category=e.target.value;render(false);return;}if(e.target.name==='notApplicable'){$('#years').disabled=e.target.checked;if(e.target.checked)$('#years').value='';}});
document.addEventListener('submit',e=>{if(e.target.id!=='profile-form')return;e.preventDefault();if(!e.target.reportValidity())return;const f=new FormData(e.target);state.profile={age:f.get('age')===''?null:Number(f.get('age')),gender:f.get('gender'),profession:String(f.get('profession')).trim(),years:f.get('years')===null||f.get('years')===''?null:Number(f.get('years')),notApplicable:f.get('notApplicable')==='on',city:String(f.get('city')).trim()};state.profileAsked=true;launch();});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.phase!=='travel')render(false);},150);});
render(false);
